using System;using System.IO;using System.Diagnostics;using System.Web.Script.Serialization;
class ProcessJobTests {static void Main(string[] args){string file=Path.Combine(args[0],"child.pid");var start=new ProcessStartInfo("powershell.exe","-NoProfile -Command \"[IO.File]::WriteAllText('"+file+"',[string]$PID); Start-Sleep -Seconds 30\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden};using(var p=Process.Start(start)){using(var job=new OfficeProcessJob()){job.Attach(p);for(int i=0;i<60&&!File.Exists(file);i++)System.Threading.Thread.Sleep(50);if(!File.Exists(file))throw new Exception("Fixture did not start");}if(!p.WaitForExit(3000))throw new Exception("Owned process did not stop");}File.WriteAllText(Path.Combine(args[0],"process-job.json"),"{\"ok\":true,\"check\":\"disposing conversion job stops owned process\"}");Console.WriteLine("Conversion process cancellation check passed");}}
